"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["9319"],{22866(e){e.exports=JSON.parse('{"id":"FIN-1132","slug":"gross-revenue-retention","term":"Gross Revenue Retention (GRR)","also_known_as":["GRR"],"difficulty":"Advanced","definition":"Gross revenue retention (GRR) is the percentage of recurring revenue a company keeps from its existing customers over a period after downgrades and cancellations, ignoring any expansion revenue.","explanation":["GRR measures how well a company holds on to the revenue it already has. Because upgrades and expansion are excluded, it can never exceed 100%.","It is calculated by taking recurring revenue from existing customers at the start of the period, subtracting revenue lost from downgrades and cancellations, and dividing by the starting revenue.","For example, a company starts the year with 10,000,000 of annual recurring revenue. It loses 500,000 through downgrades and 700,000 through cancellations. Its GRR is 8.8 million divided by 10 million, or 88%.","GRR complements net revenue retention. A company may have strong NRR because a few customers expanded a lot, while still losing many others. GRR reveals this underlying loss. A high GRR suggests customers find the product essential and are unlikely to leave. It is particularly important for judging the stability of a subscription business\'s revenue base."],"note":"","total":1500,"prev":{"slug":"gross-profit","term":"Gross Profit"},"next":{"slug":"growing-annuity","term":"Growing Annuity"}}')}}]);